import type { Concept } from "../types";

function cx(
  id: string,
  title: string,
  simple: string,
  technical: string,
  analogy: string,
  command: string,
  output: string,
  explanation: string,
  q: string,
  a: string,
  related: string[],
  takeaway: string,
  real?: Real,
): Concept {
  return {
    id,
    title,
    simple,
    technical,
    analogy,
    example: { command, output, explanation },
    mistakes: real?.mistakes ?? GENERIC.mistakes,
    practices: real?.practices ?? GENERIC.practices,
    exercise: real?.exercise ?? {
      prompt: `After reading “${title}”, write one sentence you could tell a junior teammate.`,
      solution: takeaway,
    },
    interview: { question: q, answer: a },
    related,
    takeaway,
  };
}

/**
 * The per-concept content that used to be missing.
 *
 * Every concept built by cx() shared one pair of mistakes, one pair of
 * practices, and an "exercise" that asked the reader to restate the takeaway
 * — which is not an exercise, and told nobody anything specific about the
 * subject. Supplying `real` replaces the placeholders with content that is
 * actually about this concept.
 */
interface Real {
  mistakes: string[];
  practices: string[];
  exercise: { prompt: string; solution: string };
}

/** Placeholders. GENERIC_COUNT in index-stats tracks how many remain. */
export const GENERIC = {
  mistakes: ["Skipping the simple model and jumping to flags.", "Copying a command without knowing which process it changes."],
  practices: ["Explain it out loud in one sentence before you run it.", "Check man or --help for the exact flag dialect (GNU vs BSD)."],
};

export const extraConceptsMore: Record<string, Concept[]> = {
  architecture: [
    cx("syscalls-plain", "System calls are the only legal door", "Because programs cannot touch hardware themselves, they have to ask, and there is a fixed list of things they are allowed to ask for. That list is the system calls, and there are only a few hundred of them: open a file, read from it, write to it, start a new process, map some memory, make a network connection. Everything your computer does is built out of that small vocabulary. You never need to memorise the list, but knowing it exists changes how you read errors: Permission denied is not your program failing, it is the kernel declining a request.", "glibc wraps those requests. strace prints them. Section 2 of the manual is the syscall list. Root is still a user-space identity.", "A hotel guest (app) fills a request form (syscall). Staff (kernel) enter the service corridors.", "man 2 syscalls | head", "syscalls(2)", "You do not memorize every syscall. You remember that Permission denied is usually the kernel saying no.", "Root vs kernel mode?", "Root is uid 0 in user space. Kernel mode is a CPU privilege level. Root still uses syscalls.", ["process-model"], "If it needs hardware or isolation, it goes through a syscall.", { mistakes: ["Reading 'Permission denied' as a bug in the program. It is the kernel refusing a request, and the fix is almost always ownership, mode bits or a security policy — not the program.", "Assuming root can bypass the system call interface. Root is still an ordinary user-space identity; it makes the same calls, the kernel just approves more of them."], practices: ["When a program fails for no visible reason, run it under strace and read the last few calls before the error. The failing syscall usually names the file or permission at fault.", "Reach for man section 2 for the kernel interface and section 3 for the C library wrapper around it — read(2) and fread(3) are not the same thing."], exercise: { prompt: "Run `strace -c ls /` if strace is available, or `strace ls / 2>&1 | head -20`. Identify which system calls are used to list a directory.", solution: "You will see openat on the directory, then getdents64 to read its entries, then write to print them, and close. Listing a directory is three or four distinct requests to the kernel, not one 'list' operation — there is no such syscall." } }),
    cx("shared-libs", "Why ldd matters", "Nearly every program needs the same basic things: formatting text, doing arithmetic on dates, talking to the kernel. Rather than every program carrying its own copy, these live in shared libraries that programs borrow from when they start. It saves enormous space, but it means a program on disk is not self-contained. If the library it expects is missing, or is a different edition, the program will not start at all — and the error usually looks like the program is broken rather than a dependency being absent.", "ldd shows dynamic deps. Alpine musl cannot run a glibc binary. Static binaries skip this but are larger.", "A lamp that needs a specific wall socket.", "ldd /bin/ls | head", "linux-vdso.so.1 ... libc.so.6 => /lib/...", "This is why 'it works on my Ubuntu' fails in Alpine.", "What is a missing shared library error?", "The dynamic linker cannot find a .so the binary was built against. Install the package or rebuild for that libc.", ["package-managers"], "Match libc (glibc vs musl) to the binary.", { mistakes: ["Copying a binary between distributions and expecting it to run. It carries no copy of its libraries, only the expectation that compatible ones are present.", "Reading 'No such file or directory' when starting a binary that is clearly there as a missing-binary error. It usually means a library the binary needs, or its dynamic loader, is what is missing."], practices: ["Before shipping a binary to another machine, run ldd on it and check the libraries exist on the target — particularly the C library, which differs between glibc and musl systems.", "If a binary must run anywhere, build it statically. It is larger, but it carries everything it needs and cannot fail this way."], exercise: { prompt: "Run `ldd /bin/ls` and then `ldd $(which bash)`. Note which libraries both depend on.", solution: "Both link against libc.so.6, the C library. That is the shared dependency almost everything on the system has, and the reason swapping it — as Alpine does by using musl — breaks binaries built elsewhere." } }),
  ],
  "boot-and-init": [
    cx("grub-plain", "GRUB is the chooser", "Between the firmware and Linux sits a small program whose entire purpose is to decide what to start. On most systems that is GRUB. It is the menu you sometimes see flash past, listing the kernels installed on the machine. This matters for one very practical reason: your system keeps the previous kernel after an update. If a kernel update leaves the machine unbootable — a graphics driver that no longer loads, a disk controller that stopped working — the fix is usually not reinstalling anything. It is choosing the older entry from that menu and booting normally while you work out what broke.", "UEFI → EFI binary or GRUB → vmlinuz + initrd. Kernel cmdline lives in grub config or boot loader entries.", "A receptionist who decides which manager starts the shift.", "ls /boot | head", "vmlinuz-...\ninitrd.img-...", "Those two files are the kernel and its first-aid kit (initramfs).", "How do you boot an old kernel?", "From the GRUB menu pick the previous vmlinuz. Cloud serial console if you have no screen.", ["systemd"], "Keep one known-good kernel; GRUB is your undo.", { mistakes: ["Reinstalling the system after a failed kernel update. The previous kernel is almost always still installed and one menu entry away.", "Removing old kernels to free space in /boot without leaving at least one known-good fallback. That space saving is what turns a bad update into a rescue-media job."], practices: ["Hold Shift (BIOS) or Esc (UEFI) during boot to reveal a hidden menu, and look under Advanced options for earlier kernels.", "After a kernel update on a machine you cannot physically reach, reboot while you are still able to get console access, not at the end of the day."], exercise: { prompt: "Run `ls /boot/vmlinuz-*` to see which kernels are installed, and `uname -r` to see which one you booted.", solution: "You will normally see two or more kernels listed and uname -r matching the newest. The others are your fallbacks — that is the entire safety net behind a kernel upgrade." } }),
    cx("initramfs-plain", "initramfs is a tiny Linux for finding the disk", "There is a chicken-and-egg problem at boot: the kernel needs drivers to read the root disk, but those drivers are stored on the root disk. The way out is a small, complete filesystem bundled next to the kernel and loaded straight into memory. It contains just enough — a few drivers, a few commands — to find the real disk, which may be encrypted, spread across several physical drives, or sitting on the network. Once it has unlocked and mounted the real root, it steps aside. When a machine boots to a bare emergency prompt saying it cannot find the root device, this is almost always the part that failed.", "If initramfs lacks a driver, you get an emergency shell. Rebuilding initramfs after a driver change is a real ops task.", "A flashlight you use to find the light switch.", "lsinitramfs /boot/initrd.img-$(uname -r) 2>/dev/null | head || echo 'tool optional'", "(module list)", "You are looking for disk and crypto modules.", "Why does dropping to initramfs happen?", "Root was not found: wrong UUID, missing module, LVM not started, or encrypt password.", ["disks-partitions"], "Boot failures before a login prompt are firmware, GRUB, kernel, or initramfs — not Bash.", { mistakes: ["Changing disk, RAID or encryption setup without rebuilding the initramfs. The new layout needs drivers the old image does not contain, and the machine will not boot.", "Assuming an emergency prompt means the disk has died. More often the disk is fine and the image simply lacks the driver needed to see it."], practices: ["Rebuild the image after any storage or crypto change — update-initramfs -u on Debian and Ubuntu, dracut -f on Fedora and RHEL — and reboot once to prove it works.", "Keep a bootable USB image available on any machine you care about. Recovering a broken initramfs from the running system is not possible."], exercise: { prompt: "List the contents of your initramfs with `lsinitramfs /boot/initrd.img-$(uname -r)` on Debian or Ubuntu, or `lsinitrd` on Fedora, and look for storage drivers.", solution: "You will find kernel modules for your disk controller and filesystem, plus a small set of utilities. It is a miniature working Linux whose only purpose is to reach the real one." } }),
  ],
  "directory-map": [
    cx("where-to-put-files", "Where things actually go", "The directory layout is a convention everyone follows, which is why you can sit down at a machine you have never seen and still find things. Configuration lives in /etc. Data that changes while the system runs — logs, databases, mail queues — lives in /var. Software the distribution installed lives in /usr, and its package manager owns it. Personal files live in /home. Scratch space that nobody promises to keep lives in /tmp. The rule worth internalising is that /usr belongs to the package manager: anything you put there by hand is liable to be overwritten by the next upgrade.", "FHS is the contract. Merged /usr means /bin is a symlink to /usr/bin. Do not store app state in /usr — upgrades wipe the idea of 'I installed it here forever'.", "A labeled warehouse.", "ls -ld /etc /var /usr /home /tmp /run", "drwxr-xr-x ...", "Say the purpose of each before you cd.", "Logs in /usr — why is that wrong?", "/usr is for shipped software; logs grow and belong in /var so you can mount it separately.", ["fhs-deep-dive"], "If it changes while the app runs, it is probably /var, /home, or /run — not /usr.", { mistakes: ["Installing software by hand into /usr. The package manager owns that tree and an upgrade can overwrite or remove your files without warning. Use /usr/local or /opt.", "Keeping application state in /usr or alongside the program. It belongs in /var, which is the tree that is meant to change and the one backup policies assume is important."], practices: ["Put anything you install manually in /usr/local, and anything self-contained from a vendor in /opt. Both exist precisely so the package manager never touches them.", "When you meet an unfamiliar server, read /etc for how it is configured and /var/log for what it has been doing. Those two answer most questions."], exercise: { prompt: "Run `ls /usr/local` and `ls /opt`. Then run `du -sh /var/log` to see how much your logs occupy.", solution: "On a fresh system /usr/local and /opt are nearly empty, which is the point — anything there was added locally rather than by the distribution. /var/log growing without limit is a common cause of a full disk." } }),
    cx("tmp-vs-run", "/tmp versus /run", "Two directories hold temporary things, and the difference matters. /tmp is general scratch space that any user may write to; it is cleaned periodically and on many systems survives a reboot, so it is not as temporary as the name suggests. /run exists only in memory and is wiped completely at every boot. It holds the things that describe the currently running system — which process IDs services are using, the sockets programs talk to each other through. Because /run lives in RAM it is small, and a program that fills it can stop unrelated services from starting.", "systemd-tmpfiles cleans /tmp. Putting secrets in /tmp is a classic leak. /dev/shm is another tmpfs.", "Sticky notes on a fridge (/tmp) vs a whiteboard erased every morning (/run).", "df -h /tmp /run 2>/dev/null | cat", "tmpfs ... /run", "/run filling up can break services (no room for sockets).", "Why sticky bit on /tmp?", "World-writable, but you can only delete your own files.", ["special-bits-acl"], "Never put passwords in /tmp.", { mistakes: ["Writing secrets to /tmp. It is world-readable by default and may outlive the process that wrote it; another user on the machine can simply read the file.", "Expecting anything in /run to survive a reboot. It is memory, so it starts empty every time, by design."], practices: ["Create temporary files with mktemp rather than a fixed name. It picks an unpredictable name and avoids both collisions and a well-known class of symlink attack.", "Use your own directory under /run for service runtime state, and let systemd create it with RuntimeDirectory= so it is cleaned up when the service stops."], exercise: { prompt: "Run `df -h /tmp /run` and compare the sizes, then run `ls /run` to see what lives there.", solution: "/run is typically a small tmpfs sized at a fraction of RAM, holding PID files and sockets. /tmp is often on the root filesystem and much larger — which is why filling /tmp fills your disk." } }),
  ],
  "help-systems": [
    cx("how-to-read-man", "How to actually read a man page", "A manual page is not meant to be read top to bottom, and trying to is why people conclude the manuals are useless. It has a fixed structure, and you jump to the part you need. SYNOPSIS shows the shape of the command — which arguments are required, which are optional. DESCRIPTION explains what it does. The options list is a reference you scan, not prose you read. Most pages end with EXAMPLES, which is frequently the fastest route to an answer, and SEE ALSO, which names the related commands. Inside the pager, slash searches and q quits.", "Sections: 1 commands, 2 syscalls, 5 file formats, 8 admin. man 5 passwd is not the passwd command.", "A book with numbered wings.", "man man", "MAN(1)", "Learning the pager is a real skill.", "man -k vs apropos?", "They search the whatis database by keyword when you forgot the command name.", ["bash-basics"], "Professionals answer flag questions with man, not a random blog.", { mistakes: ["Reading the options list from the top looking for the right flag. Search for it instead: press slash, type the flag, press Enter.", "Assuming one page per name. man passwd is the command; man 5 passwd is the file format. Reading the wrong section explains a surprising amount of confusion."], practices: ["Jump to the end first. EXAMPLES and SEE ALSO answer more real questions than the options list does.", "Use man -k (or apropos) to search by what you want to do when you do not know the command's name."], exercise: { prompt: "Open `man ls`, press slash, type `-h`, and press Enter to jump to the human-readable option. Then press q and run `man -k directory | head`.", solution: "Searching takes you straight to the -h description. apropos lists every page mentioning directories, which is how you find a command whose name you do not yet know." } }),
    cx("help-flags", "--help, info, and tldr", "There are several places to get help and they are not equivalent. Most programs accept --help and print a short summary, which is usually enough to remind you of a flag. The full manual is man. GNU projects often ship a longer, hyperlinked manual readable with info. Community-written tldr pages give you a handful of common examples with no theory, which is excellent for remembering syntax and a bad source of truth for anything in production. The catch: some commands are built into the shell rather than being programs on disk, and those do not have manual pages at all — you ask the shell with help instead.", "Bash builtins use help cd. type pwd tells you if it is builtin or a disk binary.", "A restaurant: --help is the daily specials; man is the full menu.", "type pwd; help pwd | head", "pwd is a shell builtin", "Builtins do not have the same flags as /bin/pwd.", "Why does man pwd differ from help pwd?", "help documents the Bash builtin; man 1 pwd documents the standalone binary.", ["env-and-path"], "Always ask: builtin or external binary?", { mistakes: ["Running man cd and concluding the system is broken. cd is built into the shell, has no separate manual page, and is documented with help cd.", "Copying a tldr example into production without checking the manual. Those pages are community-written, abbreviated, and sometimes out of date for your version."], practices: ["Run type <command> first when something behaves unexpectedly. It tells you whether you are using a shell builtin, an alias, a function, or a program on disk — and they differ.", "Reach for --help to jog your memory and man when you need to be certain. Treat tldr as a reminder, never as the source."], exercise: { prompt: "Run `type cd`, `type ls`, and `type echo`. Then try `help echo` and `man echo` and compare.", solution: "cd is a shell builtin, ls is a file on disk, and echo is usually both — a builtin that shadows /bin/echo. That is why echo's behaviour can differ between shells even though a program by that name exists." } }),
  ],
  "terminal-shell": [
    cx("ctrl-keys", "Ctrl-C, Ctrl-Z, Ctrl-D", "Three key combinations do very different things, and confusing them is a common source of lost work. Ctrl-C interrupts: it asks the running program to stop, and well-behaved programs clean up before exiting. Ctrl-Z suspends: the program is frozen, not finished, and it is still sitting there using memory — you bring it back with fg. Ctrl-D is not a stop at all; it means end of input, as though the file you were typing had ended. That is why Ctrl-D at an empty prompt logs you out: you told the shell its input was finished.", "The terminal driver translates keys into signals or bytes. SSH uses a pty so remote programs see the same thing.", "A doorbell (signal) vs hanging up the phone (EOF).", "stty -a | head", "intr = ^C; eof = ^D; susp = ^Z", "You can remap them; do not, until you know why.", "Does Ctrl-C kill daemons?", "Only the foreground process group of that terminal. Daemons usually have no controlling tty.", ["jobs-signals"], "Ctrl-C is a request, not SIGKILL.", { mistakes: ["Using Ctrl-Z to stop something and assuming it is gone. It is suspended and still holding its memory and files open; it will still be there when you close the terminal.", "Pressing Ctrl-C repeatedly during a long shutdown or a database operation. The first one asked it to stop cleanly; the rest may force an unclean exit instead."], practices: ["After Ctrl-Z, run jobs to see what you suspended, then fg to resume it or kill %1 to end it properly.", "If Ctrl-C does not work, the program is ignoring the interrupt. Suspend it with Ctrl-Z and send a stronger signal rather than closing the window."], exercise: { prompt: "Run `sleep 300`, press Ctrl-Z, then run `jobs`. Bring it back with `fg`, then stop it properly with Ctrl-C.", solution: "jobs shows the sleep as Stopped — suspended, not finished. fg resumes it in the foreground, and Ctrl-C then ends it. Closing the terminal with it suspended would have left it to be killed abruptly." } }),
    cx("tmux-later", "Why people use tmux", "When you run a long job over SSH and the connection drops, the job dies with it, because everything you started belonged to that session. A terminal multiplexer fixes this by putting your shell in a session that lives on the server independently of your connection. You attach to it, work, detach or get disconnected, and reattach later from anywhere to find everything exactly as you left it — still running. It also splits one window into several panes. The splitting is the part people notice first; the surviving-a-dropped-connection part is the reason it is on every server.", "tmux/screen attach to a session. systemd lingering and mosh are related ideas.", "A desk that stays tidy when you leave the room.", "tmux -V 2>/dev/null || echo 'install later'", "tmux 3.x", "Optional on servers; invaluable on long jobs.", "tmux vs nohup?", "tmux is an interactive session. nohup/disown/systemd are for detaching one process.", ["process-model"], "Do not start with tmux on day one — but know it exists for remote work.", { mistakes: ["Starting a long migration or upgrade directly over SSH. A dropped connection halfway through a package upgrade can leave the system in a state that needs manual repair.", "Opening a multiplexer inside another one by habit and then wondering why the prefix key no longer reaches the session you meant."], practices: ["Start any job longer than a coffee break inside tmux or screen, so a lost connection is an inconvenience rather than an incident.", "Name your sessions with tmux new -s upgrade, so reattaching later tells you which is which."], exercise: { prompt: "Run `tmux new -s test`, start `sleep 600`, detach with Ctrl-B then d, and reattach with `tmux attach -t test`.", solution: "The sleep is still running after detaching, because it belongs to the tmux session on the server rather than to your SSH connection. Closing the terminal entirely and reconnecting shows the same thing." } }),
  ],
  "bash-basics": [
    cx("exit-codes", "Zero means success", "Every command leaves behind a number when it finishes, and that number is how the shell knows whether it worked. Zero means success; anything else means some kind of failure. You can see the last one with echo $?. This is not a detail for script authors only — it is the mechanism behind everything conditional in the shell. When you write one command && another, the second runs only because the first returned zero. A few values are worth recognising: 127 means the command was not found at all, 126 means the file was found but is not executable, and 130 means it was interrupted with Ctrl-C.", "Pipelines: only the last command's status unless set -o pipefail. 127 is command not found. 126 is not executable.", "A stamp on homework: 0 is pass.", "false; echo $?", "1", "false is a real command whose job is to fail.", "Why check $? in scripts?", "To stop on failure instead of charging ahead with a missing file.", ["bash-scripting"], "Always know whether the last command succeeded.", { mistakes: ["Checking $? after already running another command. It holds the status of the most recent command only, and even an echo overwrites it — capture it immediately if you need it.", "Assuming a pipeline failed if any part of it failed. By default the status is the last command's only, so a failing command piped into grep reports success."], practices: ["Set -o pipefail in scripts where a pipeline failing silently matters. Without it, curl url | tar -x hides a failed download.", "Return a meaningful non-zero status from your own scripts. Anything that calls them, including cron and CI, uses that number to decide what happened."], exercise: { prompt: "Run `true; echo $?` then `false; echo $?`, then `ls /nonexistent; echo $?`. Finally run `false | grep x; echo $?` and explain the result.", solution: "You get 0, 1, and 2. The pipeline reports grep's status rather than false's — it prints 1 because grep found nothing, and the failure of false is invisible. That is what pipefail exists to fix." } }),
    cx("type-command", "How the shell finds ls", "When you type a name, the shell does not simply look for a program with that name. It works through a priority order: first aliases you defined, then shell functions, then commands built into the shell itself, and only then does it search the directories in PATH. This is why the thing that runs may not be the file you expect. The type command tells you exactly what will happen, which makes it the first thing to run whenever a command behaves differently from the documentation — frequently because an alias or function is quietly intercepting it.", "hash caches the path. After an install, hash -r. command ls skips aliases.", "Looking through labeled drawers in order.", "type ls; command -v ls", "ls is hashed (/usr/bin/ls)", "command -v is the portable cousin.", "alias vs PATH?", "Aliases are expanded first in interactive shells and usually not in scripts unless you shopt.", ["env-and-path"], "When the 'wrong ls' runs, type is the first debug tool.", { mistakes: ["Installing a newer version of a tool and finding the old one still runs. The shell caches the location it found earlier; hash -r clears that memory.", "Debugging strange behaviour without noticing an alias is involved. An alias for rm or ls defined in a shell profile will not appear in any manual page."], practices: ["Run type <name> before you reach for strace. It resolves a surprising share of 'this command is behaving oddly' in one step.", "Prefix a command with a backslash to bypass an alias for one invocation, or use command <name> to skip aliases and functions deliberately."], exercise: { prompt: "Run `type -a ls`. Then define `alias ls='ls --color=never'` and run `type ls` again.", solution: "type -a lists every candidate in priority order. After the alias, type reports the alias first — that is now what runs, and \\ls or command ls is how you reach the real one." } }),
  ],
  "env-and-path": [
    cx("export-plain", "export makes children see it", "A variable you set belongs only to the shell you set it in. If you run a program from that shell, the program does not see it — unless you exported it. Exporting marks a variable to be copied into every program the shell starts afterwards. This explains a problem that confuses everyone at least once: you set a variable, your script works, you put the same thing in cron, and it fails. Cron starts your script from a near-empty environment, so everything your interactive shell exported from its startup files is simply not there.", "VAR=value cmd runs one command with an extra variable. env -i starts a clean environment — that is why cron surprises you.", "A note on your desk vs a memo sent to the next room.", "export | head", "declare -x PATH=...", "PATH is exported so every command can find binaries.", "Why did my script not see MYVAR?", "You set it in an interactive shell without export, or the script is a new process with a fresh environment.", ["quoting-expansion"], "If a child must see it, export it — or pass it on the command line.", { mistakes: ["Setting a variable without export and wondering why the program you launch cannot see it. The variable exists, just not for children.", "Assuming cron or a systemd service inherits your shell environment. Neither reads your profile, so PATH and any variable you rely on must be set explicitly."], practices: ["Pass a variable to a single command by prefixing it: VAR=value command. It affects that one run and nothing else.", "When a script works by hand and fails under cron, reproduce it with env -i to start from an empty environment. The difference is almost always the cause."], exercise: { prompt: "Run `GREETING=hello` then `bash -c 'echo $GREETING'`. Now run `export GREETING` and repeat the second command.", solution: "The first prints an empty line because the child shell never received the variable. After export, it prints hello. That gap is exactly why cron jobs fail in ways you cannot reproduce interactively." } }),
    cx("dot-on-path", "Never put . on PATH", "PATH is a list of directories the shell searches for commands, separated by colons. If the current directory appears in that list — written as a dot, or as an empty gap between two colons, or a stray colon at either end — then any file in whatever directory you happen to be sitting in can run as a command. That is a genuine security problem: someone leaves a file named ls in a shared or downloaded folder, you cd into it and type ls, and their file runs instead of the real one, with your privileges.", "This is a classic privilege trick. Cron with a short PATH is safer than a clever PATH.", "Leaving the spare key under the doormat.", "echo \"$PATH\"", "/usr/local/bin:/usr/bin:/bin", "No empty :: segments, no .", "How do you run a script in . safely?", "./script.sh — the slash means 'this path', not PATH lookup.", ["linux-security"], "Type ./ for local scripts. Keep PATH to trusted directories.", { mistakes: ["Appending to PATH carelessly with PATH=$PATH: and leaving a trailing colon. An empty component means the current directory just as surely as a dot does.", "Putting the current directory on root's PATH for convenience. It converts any writable directory on the system into a way to run code as root."], practices: ["Run a program in the current directory explicitly with ./program. It is two extra characters and removes the need for a dot on PATH at all.", "Set PATH explicitly at the top of cron jobs and scripts rather than inheriting whatever is there. A short, known PATH is safer than a clever one."], exercise: { prompt: "Run `echo \"$PATH\" | tr ':' '\\n' | cat -A | head` and look for empty lines or a lone dot.", solution: "Every line should be an absolute path. An empty line, or one containing only a dot, means the current directory is searched for commands — fix it in the shell profile that set it." } }),
  ],
  "quoting-expansion": [
    cx("glob-plain", "Globs happen before the program runs", "When you type an asterisk, the program you are running never sees it. The shell expands the pattern into a list of matching filenames first, then hands that list to the program as separate arguments. So rm *.txt is not rm receiving a pattern; it is rm receiving twenty filenames. This explains several things at once: why a command can fail with 'argument list too long', why quoting a pattern changes the behaviour completely, and why a pattern that matches nothing is passed through unchanged as a literal string rather than becoming an empty list.", "set -f disables globbing. nullglob changes empty-match behavior in Bash.", "You unpack a box (glob) before handing items to a worker (the command).", "echo *", "(filenames)", "echo '*' prints a star.", "Why did rm * delete more than you thought?", "The shell expanded * to every name, including ones you did not look at.", ["practical-scripts"], "Quote variables. Only glob when you mean 'all these files'.", { mistakes: ["Expecting a command to receive the pattern itself. Tools such as find that do their own matching need the pattern quoted, or the shell consumes it first.", "Running a destructive command with a pattern you have not inspected. The shell expands it with no confirmation step, and rm cannot tell you what it was about to delete."], practices: ["Preview any destructive pattern by running echo with it first. echo rm *.txt shows the exact command that would run.", "Quote patterns meant for the program rather than the shell: find . -name '*.log' passes the pattern to find, where it belongs."], exercise: { prompt: "In an empty directory run `echo *.txt`, then create a file and run it again. Compare with `echo '*.txt'`.", solution: "With no matches the shell passes *.txt through literally, which is why a loop over a non-matching pattern can process a file that does not exist. Quoted, it is always literal. Bash's nullglob option changes the first behaviour." } }),
    cx("word-split", "Word splitting is the silent bug", "An unquoted variable does not stay a single value. The shell takes whatever is inside it and splits it apart wherever there are spaces, tabs or newlines, handing each piece to the command as a separate argument. If a variable holds a filename containing a space — My Documents — then using it unquoted passes My and Documents as two arguments. This is the single most common bug in shell scripts, and it is dangerous rather than merely annoying, because a script that works on every file you tested will do something unintended the first time it meets a space.", "IFS newline hacks exist; arrays are better in Bash. POSIX: quote \"$@\".", "A sentence ripped at every space.", "name='a b'; printf '%s\\n' $name", "a\nb", "Quoted \"$name\" stays one word.", "[ $x = 1 ] without quotes?", "If x is empty, test sees too few arguments and errors. Always [ \"$x\" = 1 ].", ["bash-scripting"], "Quote variables by default. Unquoted is the exception you can explain.", { mistakes: ["Writing rm $file instead of rm \"$file\". It works until a filename contains a space, at which point it deletes the wrong things.", "Looping over the output of ls. Filenames can contain spaces and newlines, so the split is unreliable; glob directly over the files instead."], practices: ["Quote every variable expansion unless you specifically want it split. \"$file\" and \"$@\" should be the default, and the unquoted form the deliberate exception.", "Run shellcheck over scripts. Unquoted expansions are its most common finding and it catches them reliably."], exercise: { prompt: "Run `name='a b'; printf '[%s]\\n' $name` then `printf '[%s]\\n' \"$name\"`.", solution: "The first prints two bracketed lines, proving the single value became two arguments. The second prints one. Every argument in a script that handles real filenames needs the second form." } }),
  ],
  "inodes-and-links": [
    cx("hard-vs-soft", "Hard link vs symlink — the interview pair", "A file's name and the file itself are separate things. The data, along with its size, owner and permissions, lives in a record called an inode; a directory entry is just a name pointing at one. A hard link is a second name pointing at the very same inode — not a copy, and not subordinate to the first. Both names are equally real, and deleting either leaves the data untouched while the other remains. A symbolic link is a different animal entirely: a small file that merely contains a path as text. If the thing at that path disappears, the symlink remains and points at nothing.", "Hard links cannot cross filesystems and cannot usually name directories. rm of one name does not delete data until the last link (and open fds) are gone.", "Two catalog cards for one book (hard) vs a sticky note saying 'see aisle 4' (soft).", "man ln | head", "LN(1)", "ln file hard; ln -s file soft", "Which survives if you rename the target?", "A hard link still points at the inode. A relative symlink may break.", ["mounts"], "Same inode number = hard link. A path string = symlink.", { mistakes: ["Expecting a symlink to keep working after its target is moved or renamed. It stores a path, not a reference to the file, so it breaks silently.", "Thinking a hard link is a shortcut to an original. There is no original — the names are peers, and the data survives until the last one is removed."], practices: ["Prefer symlinks for anything crossing filesystems or pointing at a directory; hard links cannot do either.", "Use ls -li to see inode numbers when you need to know whether two names are the same file. Identical inode numbers mean identical data."], exercise: { prompt: "Run `echo hi > a; ln a b; ln -s a c; ls -li a b c`. Then `rm a` and try `cat b` and `cat c`.", solution: "a and b share an inode number; c has its own. After removing a, b still prints hi because the data had two names, while c is broken — it stored the path 'a', which no longer exists." } }),
    cx("deleted-but-open", "Why df stays full after rm", "Deleting a file does not necessarily free its space. Removing a file only removes the name; the data survives as long as something still has the file open. So if a service is writing to a large log and you delete that log to reclaim disk, the service keeps its handle, keeps writing to a file that now has no name, and the space is never returned. The symptom is distinctive and baffling the first time: df says the disk is full, du adds up the visible files and finds far less, and the gap is exactly the deleted-but-still-open files.", "lsof +L1 or lsof | grep deleted. Truncate via /proc/pid/fd/N or restart the daemon.", "Throwing away the label but leaving the box in someone's hands.", "man lsof | head", "LSOF(8)", "This is the #1 disk-full surprise.", "How do you free a deleted log?", "Restart the writer, or truncate the still-open fd after confirming it is the right process.", ["process-control"], "Unlink ≠ free space if something still has the file open.", { mistakes: ["Deleting a large log to free space without restarting or signalling the process that writes it. The space stays occupied until that process closes the file or exits.", "Trusting du to explain a full disk. It can only see files that still have names, so it cannot account for this at all."], practices: ["When df and du disagree, run lsof +L1 to list open files with no remaining name. That difference is your missing space.", "Empty a live log with : > file or truncate -s 0 file instead of deleting it. The process keeps its handle and the space is actually released."], exercise: { prompt: "Run `df -h /` and note the usage. Then compare with `du -sh /var/log`. If they ever disagree sharply on a real server, run `lsof +L1 | head`.", solution: "On a healthy system the numbers are consistent. When they are not, lsof +L1 names the processes holding deleted files open — restarting that service, or truncating through /proc/<pid>/fd/, returns the space immediately." } }),
  ],
  mounts: [
    cx("fstab-plain", "fstab is the boot packing list", "The system needs to know which disks to attach at boot and where to put them, and that list lives in one file: /etc/fstab. Each line names the thing to mount, the directory it should appear at, its filesystem type, and a set of options. The important discipline is how you name the disk. Device names like /dev/sda are assigned in the order the kernel finds hardware, so adding a drive can renumber them and the machine boots with the wrong disk in the wrong place. Naming a filesystem by its UUID — a label stored inside the filesystem itself — identifies it regardless of where it is plugged in.", "nofail for optional disks. noexec on /tmp is a hardening choice. bind mounts remount a tree elsewhere.", "A seating chart for filesystems.", "findmnt --fstab 2>/dev/null | head || cat /etc/fstab | head", "UUID=... / ext4 ...", "Never copy /dev/sda from a blog onto NVMe.", "What is a bind mount?", "The same tree visible at a second path. Used in containers and chroots.", ["lvm-and-fstab"], "Identify with findmnt before umount. Persist with UUID in fstab.", { mistakes: ["Identifying disks as /dev/sda or /dev/nvme0n1 in fstab. Those names depend on detection order; adding a disk can silently reassign them and prevent boot.", "Adding an external or network mount with no nofail option. If it is absent at boot, the machine stops and waits for it rather than coming up."], practices: ["Get the UUID with lsblk -f or blkid and use UUID= in fstab. It is stable across cabling, reboots and controller changes.", "After editing fstab, run mount -a and findmnt --verify before rebooting. A typo there is discovered at the next boot otherwise, when you are least able to fix it."], exercise: { prompt: "Run `lsblk -f` to see the UUIDs of your filesystems, then `findmnt --fstab` to see how they are referenced.", solution: "A well-maintained fstab references UUIDs rather than device names. If yours uses /dev/sdX, it is one new disk away from a boot failure — and the fix is a text edit now rather than rescue media later." } }),
    cx("busy-umount", "Why umount says busy", "Unmounting a filesystem fails with 'target is busy' whenever anything is still using it, and the usual cause is less dramatic than people expect. A process has a file open on it, or has its working directory somewhere inside it — including, very often, your own shell, because you cd'd in to look around before trying to unmount. The message does not say which process, so the job is to find out. Forcing it is the wrong instinct: a lazy unmount detaches the directory from view but leaves the work in progress, which is how you end up with a filesystem that is neither mounted nor free.", "lsof +f -- /mnt or fuser -vm. lazy umount (-l) detaches the name but waits for references — use with care.", "Trying to leave a room while people are still inside.", "findmnt /", "/ /dev/... ext4", "Know the mount before you blame the app.", "lazy umount risk?", "Processes keep using the old fs; surprises later. Prefer stop-the-app then umount.", ["process-model"], "BUSY means references. Find them; do not reboot first.", { mistakes: ["Standing inside the mount point while unmounting it. Your own shell's working directory is a reference, and cd / fixes it immediately.", "Reaching for umount -l as the first response. It hides the problem by removing the name, while the writes carry on against a filesystem you believe is detached."], practices: ["Find the holder before forcing anything: fuser -vm /mnt or lsof +f -- /mnt names the processes, and usually one of them should simply be stopped.", "On a server, stop the service that uses the filesystem rather than fighting the mount. Unmounting underneath a running database is not a shortcut worth taking."], exercise: { prompt: "Pick any mount point from `findmnt`, cd into it, and try to unmount it. Then cd / and try again.", solution: "The first attempt reports the device as busy; the second succeeds, assuming nothing else holds it. Your own working directory is the most common cause of the message, and the one people check last." } }),
  ],
  "fhs-deep-dive": [
    cx("proc-self", "/proc/self is you", "/proc is not a real directory on a disk. The kernel invents its contents as you look at them, presenting live information about running processes as though it were files. Every process has a numbered directory there showing its command line, its open files, its memory and its working directory. /proc/self is a shortcut that always refers to whichever process is doing the reading, so it means something different for every reader. This is where tools like lsof and ps get their information — they are not performing magic, they are reading files, and so can you.", "This is how lsof and ss learn so much. It is not a disk you back up.", "A name tag that always says 'me'.", "ls -l /proc/self/fd", "0 -> /dev/pts/0 ...", "0,1,2 are stdin, stdout, stderr.", "Can you cd into /proc/1/root?", "With enough privilege that is the mount namespace root of PID 1 — a container-host debug trick.", ["namespaces-cgroups"], "/proc is a live API, not documents.", { mistakes: ["Trying to back up or copy /proc. There is nothing there to copy; the contents are generated on demand and are meaningless without the running process.", "Assuming a process ID in /proc stays valid. Numbers are reused after a process exits, so a directory that was one program a moment ago may now be another."], practices: ["Read /proc/<pid>/cmdline to see exactly how a process was started, including arguments that ps may have truncated.", "Use /proc/<pid>/fd to see what a process has open — including the deleted files that explain a disk which is full with nothing on it."], exercise: { prompt: "Run `ls -l /proc/self/fd` and then `cat /proc/self/cmdline | tr '\\0' ' '`.", solution: "File descriptors 0, 1 and 2 are standard input, output and error, shown as links to your terminal. cmdline shows the cat command itself — /proc/self resolved to the process doing the reading, which was cat and not your shell." } }),
    cx("sys-vs-proc", "/sys versus /proc", "Two directories present kernel information as files, and they divide the job differently. /proc is mostly about processes — one numbered directory per running program — plus a handful of system-wide settings for historical reasons. /sys describes hardware and drivers: every device the kernel knows about, organised by type, with files exposing their current settings. The crucial difference from ordinary files is that writing to them does something. Writing a number into the right file under /sys changes a device's behaviour immediately, with no confirmation and no undo.", "udev uses /sys. Do not chmod randomly here.", " /proc is HR files; /sys is the building wiring diagram.", "ls /sys/class | head", "block  net  ...", "Read-only curiosity is fine; writes are configuration.", "sysctl vs /proc/sys?", "sysctl is the friendly interface to /proc/sys knobs.", ["architecture"], "Look in /sys for devices, /proc for processes and some tunables.", { mistakes: ["Browsing /sys with a text editor. Opening these files to write is a configuration change to live hardware, not an edit you can reconsider before saving.", "Making a change under /proc or /sys and expecting it to survive a reboot. Both are rebuilt from scratch at every boot; persistent settings belong in sysctl configuration or udev rules."], practices: ["Read freely, write deliberately. cat anything you like; redirect into these files only when you know what the value means.", "Make kernel settings permanent in /etc/sysctl.d rather than by writing to /proc/sys at runtime, so the machine comes back the same way."], exercise: { prompt: "Run `ls /sys/class` to see device categories, then `cat /sys/class/net/*/operstate` to see which network interfaces are up.", solution: "/sys/class groups devices by kind, and operstate reports up or down per interface. This is the same information ip link shows, read directly from the files the tool itself reads." } }),
  ],
  "users-groups": [
    cx("sudo-vs-su", "sudo versus su", "Both commands let you act as another user, usually root, but they work on opposite principles. su switches you into that account, and to do it you must know that account's password — so everyone who needs root shares one secret, and the logs show only that root did something. sudo keeps you as yourself: you authenticate with your own password, and a policy file decides which commands you are permitted to run. That difference is why sudo won. It lets you grant exactly one command to one person, revoke it by editing a file, and keep a log that names who actually ran it.", "visudo edits /etc/sudoers. NOPASSWD is convenient and dangerous. sudo -i is a root login shell.", "A guest badge for one room (sudo) vs taking the master key (su).", "sudo -l | head", "(policy)", "See what you are allowed to run.", "Why visudo?", "It syntax-checks sudoers so you cannot lock yourself out with a typo as easily.", ["linux-security"], "Prefer sudo with a tight command list over sharing the root password.", { mistakes: ["Editing the sudo policy with a normal text editor. A syntax error can lock everyone out of administrative access; visudo checks the file before saving precisely to prevent that.", "Granting broad NOPASSWD access for convenience. It removes the pause that stops a mistyped command, and turns any compromise of that account into immediate root."], practices: ["Run sudo -l to see exactly what you are permitted to run on a machine before assuming you have, or lack, access.", "Grant specific commands rather than full root where you can. The point of sudo is the granularity; using it only to become root discards that."], exercise: { prompt: "Run `sudo -l` and read what it reports. Compare `sudo whoami` with `whoami`.", solution: "sudo -l lists the commands your account may run and as whom. whoami prints your own name, sudo whoami prints root — the same process, running as a different identity for one command." } }),
    cx("nsswitch-plain", "passwd file is not always the whole story", "Looking up a user is not necessarily reading /etc/passwd. The system consults a configured list of sources in order, and the local file is only the first of them. On a machine joined to a company directory, most accounts exist in LDAP or Active Directory and appear nowhere in /etc/passwd at all. This is why a script that greps the file reports that a real, working user does not exist. The getent command asks the system the same way everything else does, following whatever sources are configured, and gets the right answer on every kind of machine.", "Cloud images may use none of this and rely on cloud-init users.", "A front desk that checks local roster then HQ.", "getent passwd \"$USER\"", "student:x:1000:1000:...", "Use getent in scripts.", "What is the x in passwd?", "Password hash lives in /etc/shadow, not in the world-readable passwd file.", ["mode-bits"], "Identity is UID. Names are labels. NSS may come from the network.", { mistakes: ["Checking whether a user exists with grep on /etc/passwd. On any directory-joined system it will miss most of the real accounts.", "Assuming the same applies only to users. Groups, hostnames and services are resolved through the same mechanism, so grepping /etc/hosts has the identical flaw."], practices: ["Use getent passwd <name> in scripts. It returns nothing and a non-zero status when the user genuinely does not exist, which is exactly the test you want.", "Read /etc/nsswitch.conf when lookups behave unexpectedly. It names the sources and their order, and the answer is usually visible there."], exercise: { prompt: "Run `getent passwd \"$USER\"` and `grep \"^$USER:\" /etc/passwd`. Then look at `cat /etc/nsswitch.conf | grep passwd`.", solution: "On a standalone machine both return the same line. On a directory-joined one, getent finds the user and grep does not — and nsswitch.conf shows why, by listing the extra sources after files." } }),
  ],
  "mode-bits": [
    cx("directory-x", "Execute on a directory means enter", "Permissions on a directory do not mean what the same letters mean on a file, and this catches almost everyone. Read on a directory lets you list the names inside it. Execute lets you go into it and reach a file whose name you already know. Write lets you create and delete names within it. The consequences are not intuitive: a directory with execute but not read means you can open a file inside it if you know its exact name, but cannot discover what is there. And because deleting is a change to the directory, you can delete a file you have no permission to read, as long as you can write to the directory holding it.", "A file 400 with a directory 100 can still be opened if you know the name — until you also need to list. Interviews love this.", "A hallway light (x) vs a directory sign (r).", "man chmod | head", "CHMOD(1)", "Symbolic u+x is safer than 777.", "Why 777 is a bad fix?", "Anyone can replace binaries, dump secrets, or implant scripts. Fix the owner/group/mode instead.", ["special-bits-acl"], "For directories, x is 'can I go in?', not 'can I run a program'.", { mistakes: ["Removing execute from a directory to restrict it, and breaking every path that passes through it. Without execute nobody can reach anything below it, however open those files are.", "Assuming write permission on a file protects it from deletion. Deletion is governed by the directory's permissions, not the file's."], practices: ["Grant execute without read on a directory when users should reach known paths but not enumerate the contents — a common pattern for home directories.", "Use symbolic modes such as chmod u+x rather than numbers when changing one bit. It leaves the others alone and makes the intent readable."], exercise: { prompt: "Run `mkdir -p d && echo secret > d/f && chmod 100 d`, then try `ls d` and `cat d/f`.", solution: "ls is refused but cat succeeds, because you knew the name. Execute alone grants passage, not discovery — which is the whole distinction, and a standing interview question." } }),
    cx("umask-plain", "umask is the subtraction", "When a program creates a file it asks for generous permissions, and the system removes some of them on the way out. That removal is the umask: a set of bits that are subtracted from what was requested. Files are requested as 666 and directories as 777, so a umask of 022 produces files readable by everyone and writable only by you, while 077 produces files only you can see at all. The value is inherited by every program you start, which is why a file created by a service can have different permissions from one you create by hand — the service was started with a different umask.", "Processes inherit umask. Shared-dir workflows use 002 plus setgid.", "A cookie cutter that removes bits before the file is born.", "umask", "0022", "Leading 0 is octal.", "Why did my service create 666 files?", "It started with umask 000. Set UMask= in systemd or call umask in the unit.", ["systemd"], "If new files are too open, look at umask before blaming chmod later.", { mistakes: ["Fixing permissions after the fact with chmod instead of setting the umask. Every new file has the wrong permissions again, and there is a window where it was readable.", "Setting a umask in an interactive shell profile and expecting services to honour it. Daemons do not read your profile; their umask comes from the service manager."], practices: ["Use 077 for anything handling private data, so new files are unreadable by other users from the moment they exist rather than from the moment you remember.", "For a shared project directory, combine umask 002 with the setgid bit so new files are group-writable and keep the right group automatically."], exercise: { prompt: "Run `umask`, then `touch f1 && ls -l f1`. Now run `umask 077 && touch f2 && ls -l f2` and compare.", solution: "With the usual 022 you get rw-r--r--, which is 666 minus 022. With 077 you get rw-------, because the group and other bits were removed. The file was requested identically both times." } }),
  ],
  "special-bits-acl": [
    cx("setuid-plain", "setuid in one sentence", "Normally a program runs with your identity and your permissions. A setuid program is the exception: it runs as whoever owns the file, regardless of who started it. The reason this exists is that some ordinary tasks genuinely need privilege — changing your own password writes to a file only root may touch — so the passwd program is owned by root and marked setuid, and briefly acts as root on your behalf. It is also the single most dangerous bit on the filesystem, because any flaw in such a program becomes a way for any user to act as its owner. Linux refuses to honour it on scripts for exactly that reason.", "Attackers love writable setuid binaries. Prefer capabilities or sudo.", "A sealed company stamp the program may use.", "ls -l /usr/bin/passwd", "-rwsr-xr-x ...", "s in the owner x slot is setuid.", "Why not setuid bash?", "That would give a root shell to anyone who can run it. Distros do not ship that.", ["linux-security"], "setuid is a sharp tool. Inventory it; do not add it casually.", { mistakes: ["Setting setuid on a shell script expecting it to gain privilege. The kernel ignores it on interpreted files, because the race between reading the file and running it is unfixable.", "Adding setuid to solve a permission problem. It is almost never the right tool; sudo with a specific rule, or a file capability, gives the same result without granting the whole program's power."], practices: ["Audit the setuid programs on a machine you inherit with find / -perm -4000 -type f. The list should be short and familiar.", "Prefer capabilities over setuid when a program needs one specific privilege — setcap cap_net_bind_service grants the ability to bind a low port without granting root."], exercise: { prompt: "Run `ls -l /usr/bin/passwd` and look at the owner's execute position. Then run `find /usr/bin -perm -4000 -type f 2>/dev/null | head`.", solution: "An s where x would be means setuid. The list from find is every program on that path that runs as its owner rather than as you — each one is a potential route to that owner's privileges, which is why the list should be reviewed and short." } }),
    cx("acl-mask", "ACLs when owner/group/other is not enough", "The classic permission model has room for exactly three parties: the owner, one group, and everyone else. That is often not enough — you may need to give one extra person access to one directory without changing its group or opening it to all. Access control lists add that: named users and named groups, each with their own permissions, stored alongside the file. The complication is the mask, a ceiling that limits what any of those extra entries can actually grant. An entry can say a user has write access while the mask quietly caps it at read, which is why permissions can look right in getfacl and still not work.", "NFS and some backup tools mishandle ACLs. Know if you rely on them.", "Extra names on the guest list.", "getfacl . | head", "# file: .", "If getfacl is missing, install acl.", "ls -l plus sign?", "Often means an ACL (or selinux, depending on context — check getfacl and ls -Z).", ["users-groups"], "If 640 is not enough granularity, ACLs — or better group design.", { mistakes: ["Granting an ACL entry and not noticing the mask has reduced it. getfacl shows both, and the effective permission is the lower of the two.", "Assuming ACLs survive everything. Some archive tools, and some network filesystems, silently drop them — so a restore from backup can quietly lose the access rules."], practices: ["Look for a + at the end of the permission string in ls -l. That is the only hint in normal output that extra rules exist at all.", "Set default ACLs on a directory with setfacl -d so new files inherit them, rather than fixing each file after it is created."], exercise: { prompt: "Run `getfacl . | head` in your home directory. If ls -l anywhere shows a + at the end of the permissions, run getfacl on that file.", solution: "getfacl prints the owner, group and other entries even with no ACL set. Where extra entries exist you will also see a mask line, and any entry above it is capped — that gap is the usual explanation for access that was granted but does not work." } }),
  ],
  "process-model": [
    cx("fork-exec-plain", "fork then exec — how commands start", "Starting a program is two steps, not one, and the split explains a lot of shell behaviour. First the shell makes a copy of itself — a new process, identical to the parent. Then that copy replaces its own contents with the program you asked for, keeping the same process number. The parent usually waits for it to finish. This is why a script cannot change the directory of the shell that ran it: the script runs in a separate process, and when it exits, its working directory goes with it. The parent shell was never affected, which is why cd has to be built into the shell rather than being a program.", "PID stays the same across exec. File descriptors stay unless O_CLOEXEC. This is why 'cd in a script' cannot change your interactive cwd: the script is another process.", "Photocopy a waiter, then the copy puts on a chef hat.", "ps -o pid,ppid,cmd | head", "PID PPID CMD", "Your shell's parent is often systemd or tmux.", "What does exec not change?", "PID, most fds, and credentials (unless the binary is setuid).", ["jobs-signals"], "Starting a program is almost always fork+exec, not 'the kernel typing'.", { mistakes: ["Writing a script that cd's somewhere and expecting your shell to be there afterwards. It changed its own directory and then exited.", "Expecting a variable set in a script to be visible afterwards. Same reason — the script was a child process, and children cannot alter their parent's environment."], practices: ["Source a script with . script.sh when it genuinely must change your current shell's directory or variables. That runs it in the existing shell rather than a child.", "Read the parent process ID in ps when tracing what started what. The chain upward usually explains an unexpected environment."], exercise: { prompt: "Create a script containing `cd /tmp` and run it. Check `pwd` afterwards. Then run `. ./script.sh` and check again.", solution: "Running it normally leaves you where you were — the child changed its own directory and exited. Sourcing it changes your shell, because no child was created. The same distinction explains every 'my script set a variable and it vanished' question." } }),
    cx("threads-plain", "Threads share memory; processes usually do not", "A process has its own private memory, and that isolation is what stops one program corrupting another. Threads are a deliberate exception: several tasks inside one process, all sharing the same memory. That makes communication between them instant, since they are simply looking at the same variables, and it is why a web server can handle many connections without starting a new process for each. It also means a crash in one thread takes the whole process with it, and that two threads touching the same data at the same time is a bug class that does not exist between processes.", "Linux implements threads as tasks with the same VM. kill a PID kills the thread group.", "Roommates (threads) vs separate apartments (processes).", "ps -o pid,nlwp,cmd | head", "NLWP is thread count.", "High NLWP is not always bad.", "fork vs clone?", "clone is the Linux syscall underneath; flags choose what to share (threads share VM).", ["namespaces-cgroups"], "CPU% in top may be one thread. Look at the whole process too.", { mistakes: ["Reading a high thread count as a problem. A JVM or Node process with dozens of threads is normal; the number alone tells you nothing about health.", "Trying to kill a single thread by its ID. Signals are delivered to the process, so you cannot stop one thread that way — it is the whole program or nothing."], practices: ["Use ps -o pid,nlwp,comm to see thread counts per process when investigating a machine that feels loaded.", "Press H in top to show individual threads. A single runaway thread inside an otherwise idle process is invisible without it."], exercise: { prompt: "Run `ps -o pid,nlwp,comm -e --sort=-nlwp | head` to list the most thread-heavy processes on your machine.", solution: "Browsers, language runtimes and desktop services dominate the list. Each is one process in ps by default, which is why a process at 400% CPU on an 8-core machine is four busy threads rather than an error." } }),
  ],
  "jobs-signals": [
    cx("term-then-kill", "TERM, wait, then KILL", "There are two ways to stop a process and the difference matters more than people assume. The default signal asks it to shut down: the program receives the request, and a well-written one closes its files, finishes its current write, and exits cleanly. The other signal cannot be received at all — the kernel removes the process immediately, so nothing is flushed, no temporary file is cleaned up, and a database may be left mid-write. Reaching for the forceful one first is a habit worth unlearning, because the cases where it helps are rarer than the cases where it causes the corruption you then have to repair.", "systemd TimeoutStopSec then SIGKILL. kill -9 is not faster if the process is in D state.", "An eviction notice versus demolishing the building.", "kill -l | tr ' ' '\\n' | head", "SIGHUP SIGINT ... SIGKILL SIGTERM", "15 is TERM, 9 is KILL.", "Can you trap SIGKILL?", "No.", ["process-control"], "Polite stop first. KILL is last resort, not first muscle memory.", { mistakes: ["Going straight to kill -9. It denies the program any chance to flush buffers or release locks, and the damage is often worse than the hang.", "Assuming kill -9 always works. A process stuck waiting on unresponsive storage cannot be killed at all, because it is not in a state where signals are delivered."], practices: ["Send the default signal, wait a few seconds, and only then escalate. That ordering is what systemd does automatically before its stop timeout expires.", "If a process survives kill -9, check its state in ps. A D means uninterruptible sleep, and the problem is the storage or network it is waiting on, not the process."], exercise: { prompt: "Run `sleep 300 &`, note the PID, then `kill <pid>` and check with `ps`. Repeat with a process and `kill -9`.", solution: "The default stops sleep cleanly. Both work here because sleep has nothing to clean up — the difference only becomes visible with a program that holds data, which is exactly when you cannot afford to find out the hard way." } }),
    cx("nohup-disown", "HUP, nohup, and disown", "When your terminal closes, the programs you started from it are told to stop. The signal dates from the era of dial-up terminals literally hanging up, and it still fires when an SSH connection drops — which is why a long job started over SSH dies when your laptop sleeps. There are several ways around it. nohup starts a command already immune to that signal. disown removes a running job from the shell's list so it is not told when the shell exits. Both work, but for anything that genuinely needs to keep running, a terminal multiplexer or a real service definition is the better answer.", "systemd user lingering and tmux survive disconnects more cleanly for interactive work.", "Leaving a slow cooker on when you leave the house.", "man nohup | head", "NOHUP(1)", "Prefer systemd services for real daemons.", "Why did my SSH job die when I disconnected?", "The shell got HUP and forwarded it. Use tmux, systemd, or nohup.", ["systemd"], "Long jobs belong in a service or multiplexer, not a raw SSH fork.", { mistakes: ["Backgrounding a long job with & and closing the terminal. The ampersand only stops it blocking your prompt; it does not protect it from the hangup.", "Using nohup for something that should be a service. It survives the disconnect but has no restart, no logging and no way to manage it afterwards."], practices: ["Start long work inside tmux or screen. It survives disconnection and, unlike nohup, you can reattach and watch it.", "If it must run unattended and reliably, write a systemd unit. You get restart on failure, logging and a defined start order — none of which nohup provides."], exercise: { prompt: "Run `nohup sleep 300 &`, then `jobs` and `ls nohup.out`. Compare with running `sleep 300 &` and then `disown`.", solution: "nohup redirects output to nohup.out because the terminal may be gone. disown leaves output pointing at a terminal that may vanish, which is why its output can disappear even though the job survives." } }),
  ],
  "process-control": [
    cx("nice-ionice", "nice is CPU politeness, not disk", "Niceness is a hint about priority for the CPU. A high nice value means this work can wait if anything else wants to run, which is useful for a long compile or backup you do not want interfering with everything else. Two things surprise people. First, on an otherwise idle machine it makes almost no difference, because there is nothing to yield to. Second, it only affects the CPU: a process that is saturating the disk will carry on doing so however nice it is, since waiting for I/O is not something the scheduler can politely deprioritise. For that there is a separate control for I/O priority.", "Priority is 20+nice. Only root can nice below 0 on typical configs.", "Letting others cut in line.", "nice -n 10 echo ok", "ok", "Start long compiles nicer.", "renice a running PID?", "renice -n 10 -p PID", ["performance-basics"], "Measure with top/vmstat before you nice. Disk issues need iostat, not nice.", { mistakes: ["Expecting nice to fix a disk-bound job. Niceness governs CPU scheduling only; a backup hammering the disk needs ionice instead.", "Trying to raise a process's priority as a normal user. You may lower your own priority freely but not raise it back, which catches people who nice something and want to undo it."], practices: ["Start backups, compiles and batch jobs with nice -n 10 so interactive work stays responsive when the machine is busy.", "Combine with ionice -c3 for anything that reads or writes heavily. The two controls cover different resources and are needed together."], exercise: { prompt: "Run `nice -n 10 sleep 60 &` then `ps -o pid,ni,comm -p $!`. Try `renice -n 0 -p $!` as a normal user.", solution: "ps shows a nice value of 10. Lowering it back to 0 is refused without privilege — niceness is a one-way concession for unprivileged users, which is worth knowing before you nice a job you may want to speed up." } }),
    cx("zombie-parent", "Fix the parent, not the zombie", "A zombie is a process that has already finished. It holds nothing but its exit code, waiting for its parent to collect it, and it uses no memory or CPU. The entry stays in the table because the parent might still want to know how the child ended. If the parent never asks, the entry lingers. This is why killing a zombie achieves nothing — it is already dead, and the signal has nowhere to go. The thing that needs attention is the parent, which has a bug: it starts children and never collects them. A few zombies appearing and vanishing is completely normal.", "If PID 1 is your app in a container, it must reap or you need a tiny init (tini).", "Closed tickets stacked on a manager's desk.", "ps -eo stat,pid,ppid,cmd | awk '$1 ~ /Z/'", "(maybe empty)", "A few fleeting Z are normal.", "Orphan vs zombie?", "Orphan is alive, reparented. Zombie is dead, waiting for wait().", ["namespaces-cgroups"], "Piles of Z mean a broken parent, often in containers.", { mistakes: ["Trying to kill a zombie. It has already exited; the process table entry is a receipt, not a running program.", "Treating any zombie as an incident. They appear briefly whenever a child exits before its parent collects it, which is constant and harmless."], practices: ["When zombies accumulate, find the parent with ps -eo stat,pid,ppid,comm and restart that process. The parent is the bug.", "In containers, run a minimal init as PID 1 if your application starts children. PID 1 inherits orphans, and an application that does not collect them will accumulate zombies forever."], exercise: { prompt: "Run `ps -eo stat,pid,ppid,comm | awk '$1 ~ /^Z/'` to list any zombies on your machine.", solution: "Most systems show none, or one that disappears on the next run. A list that persists and grows points at a single parent process that is not collecting its children — note the PPID column, because that is what needs restarting." } }),
  ],
  "net-fundamentals": [
    cx("localhost-bind", "127.0.0.1 versus 0.0.0.0", "A program that accepts network connections has to choose which addresses to accept them on, and the choice has large consequences. Binding to 127.0.0.1 means only this machine can reach it — connections from anywhere else are not refused so much as never able to arrive. Binding to 0.0.0.0 means every network interface the machine has, which on a cloud server includes its public address. This one setting is behind a long history of accidental exposure: a database or a debugging interface started with the convenient default, reachable from the internet by anyone who scans for it.", "ss -tlnp shows the bind address. Firewalls still apply.", "A shop with a back-room phone versus a sign on the street.", "ss -tln | head", "LISTEN ... 127.0.0.1:631", "Local-only is a feature.", "ping works, app does not?", "ICMP is not TCP. Check the port with ss/curl.", ["tcp-and-sockets"], "Always read the listen address before you celebrate 'it started'.", { mistakes: ["Leaving a development server bound to 0.0.0.0 on a machine with a public address. It is reachable from the internet immediately, regardless of whether anyone was told about it.", "Assuming a firewall makes the bind address irrelevant. Firewall rules get changed, and a service bound only to localhost is safe even when they are."], practices: ["Bind to 127.0.0.1 by default and widen deliberately. Services that only a local application talks to never need anything else.", "Audit what is listening with ss -tlnp. The address column tells you immediately which services are exposed beyond the machine."], exercise: { prompt: "Run `ss -tlnp` and read the Local Address column for each listener.", solution: "Entries showing 127.0.0.1 or [::1] are local only. Entries showing 0.0.0.0 or * accept connections on every interface — on a server with a public address, each of those is reachable from the internet unless a firewall says otherwise." } }),
    cx("tcp-udp-plain", "TCP is a call; UDP is a postcard", "Two ways of sending data, with different promises. TCP establishes a connection first, then guarantees that what you send arrives, in order, with anything lost being sent again. That reliability costs a round trip to set up and some delay whenever something must be retransmitted. UDP makes no such promise: each message is sent on its own, and may arrive late, out of order, or not at all. That sounds strictly worse but is the right choice when a late packet is useless anyway — a dropped moment of audio is better replaced by the next one than by a retransmission that arrives after the conversation moved on.", "Connection refused = RST, host reached, no listener. Timeout = drop or blackhole.", "Phone call vs postcard.", "man 7 ip | head", "IP(7)", "Keep the model; details come with ss -tmi.", "Why is DNS often UDP/53?", "Small queries fit one datagram. TCP/53 is used for large responses and zone transfers.", ["name-resolution"], "Ping ≠ open port. Refused ≠ timeout.", { mistakes: ["Reading every network failure as the same thing. Connection refused means the machine answered and nothing is listening; a timeout means nothing answered at all, and they point at completely different causes.", "Assuming a UDP service is reachable because the port is open. Nothing acknowledges a UDP packet, so an open port and a black hole look identical from outside."], practices: ["Distinguish refused from timed out before investigating further. Refused is a service problem on a reachable host; timed out is routing, firewall, or the wrong address entirely.", "Test TCP reachability with ss on the server rather than guessing from the client. It shows whether anything is actually listening."], exercise: { prompt: "Run `curl -sS --max-time 3 http://127.0.0.1:9 ; echo \"exit=$?\"` and compare with a port that is firewalled or unreachable.", solution: "Port 9 on localhost gives an immediate Connection refused — the machine replied that nothing is there. An unreachable host instead hangs until the timeout. Immediate refusal versus hanging is the fastest diagnostic distinction in networking." } }),
  ],
  "name-resolution": [
    cx("hosts-then-dns", "/etc/hosts is the first cheat sheet", "Before the system asks a DNS server what a name means, it checks a local file. /etc/hosts maps names to addresses directly, and anything listed there wins without a query leaving the machine. This is genuinely useful: you can point a hostname at a test server, or make a name resolve before DNS exists. It is also a classic source of confusion that survives for months, because an entry added for an afternoon's testing is invisible to every DNS tool. dig and nslookup query DNS directly and do not read the file at all, so they will confidently report an answer the machine itself is not using.", "nsswitch.conf order: files dns. systemd-resolved adds a stub at 127.0.0.53.", "A paper address book versus the phone directory.", "getent hosts localhost", "127.0.0.1 localhost", "getent uses NSS, dig does not.", "dig works, curl does not resolve?", "dig talks to a DNS server directly. curl uses NSS (stub, search domains, mdns).", ["remote-access"], "Debug with getent first, then dig, then resolvectl.", { mistakes: ["Diagnosing a resolution problem with dig alone. dig bypasses /etc/hosts, so it can report the correct address while every program on the machine uses a stale local entry.", "Leaving a temporary hosts entry in place. It survives reboots, applies to everything on the machine, and nothing will ever remind you it is there."], practices: ["Use getent hosts <name> to see what the system will actually resolve. It follows the same order applications do, including the local file.", "Comment every hosts entry you add with the reason and the date. The alternative is debugging a ghost in six months."], exercise: { prompt: "Run `getent hosts localhost` and `cat /etc/hosts`. Then compare `getent hosts` against `dig +short` for any name in that file.", solution: "getent returns the local file's answer; dig returns what DNS says, ignoring the file entirely. When those two disagree, the machine believes getent — which is why it is the right tool for diagnosing what an application will see." } }),
    cx("default-route", "The default route is 'how packets leave'", "A machine knows how to reach networks it is directly attached to. For everything else — which is to say, the internet — it needs to be told where to send traffic, and that instruction is the default route. It names a gateway, usually the router on the local network, and means: anything you do not have a specific rule for, hand to this. Without it you get a confusing partial failure. Other machines on the same network respond normally, so the interface is clearly working, but nothing beyond it is reachable at all. It looks like DNS is broken, and it is not.", "Cloud metadata routes are extra. Wrong route is a silent outage.", "The 'exit' sign in a building.", "ip -br a; ip r", "lo UP ...\ndefault via ...", "Learn ip, not ifconfig, on modern Linux.", "DHCP vs static?", "DHCP leases address, route, and DNS. Static is pinned; document it.", ["net-fundamentals"], "If names fail, check DNS. If IPs fail, check route and firewall.", { mistakes: ["Diagnosing a missing default route as a DNS fault. Name resolution fails because the DNS server is unreachable, which makes the symptom look like a naming problem.", "Adding a second interface and acquiring a second default route. Which one wins depends on metrics, and traffic can leave by an interface that cannot carry it."], practices: ["Check routing before anything else when a machine has partial connectivity: ip route shows the default line, or its absence, in one glance.", "Test with an IP address rather than a name to separate routing from resolution. If the address works and the name does not, the problem is genuinely DNS."], exercise: { prompt: "Run `ip route` and find the line beginning with `default`. Then run `ip -br addr` to see your interfaces and addresses.", solution: "The default line names the gateway and the interface used to reach it. If that line is missing, the machine can only reach its own subnet — and every symptom will look like something else until you check this." } }),
  ],
  "remote-access": [
    cx("keys-not-passwords", "Keys beat passwords", "Logging in with a password means sending a secret to the server, and it means anyone who guesses it is you. Key authentication works differently. You generate a pair of files: a private key that never leaves your machine, and a public key you copy to every server. The server sends a challenge only the private key can answer, so the secret itself is never transmitted and cannot be captured in transit or guessed by brute force. Once keys work, turning password authentication off entirely removes the thing that automated attacks spend all day trying against every machine on the internet.", "ssh-copy-id installs the public key. ssh -vvv shows which key is offered. IdentitiesOnly yes stops spraying every key.", "A badge, not a shouted password in the hallway.", "man ssh-keygen | head", "SSH-KEYGEN(1)", "Never paste a private key into chat.", "What does host key checking stop?", "MITM: a fake server stealing credentials.", ["linux-security"], "Mode 700 on ~/.ssh, 600 on the private key, StrictModes on the server.", { mistakes: ["Copying a private key between machines, or into a chat window. The private key is the credential; it is meant to exist in exactly one place and never to be transmitted.", "Disabling password authentication before testing that the key works. Confirm the key login in a second terminal while the first is still connected, or you may lock yourself out."], practices: ["Install your public key with ssh-copy-id rather than editing authorized_keys by hand. It gets the file permissions right, and wrong permissions are the usual reason keys silently fail.", "Protect the private key with a passphrase and load it into an agent once per session. You get the convenience of no password and the safety of an encrypted key file."], exercise: { prompt: "Run `ls -l ~/.ssh/` and check the permissions. Then run `ssh -v <host>` and read which keys are offered.", solution: "Private keys must be readable only by you; SSH refuses to use one that is group or world readable, and the error rarely says so plainly. The verbose output shows each key offered in turn, which is how you tell whether the right one is even being tried." } }),
    cx("proxyjump", "Jump hosts without Swiss-cheese VPNs", "Servers that matter are usually not reachable from the internet directly. You connect to one permitted machine — a bastion — and reach everything else from there. Typing two connections every time is tedious, so SSH can do it for you: it opens the connection to the bastion and tunnels the real connection through it, so a single command reaches the target. The important property is that the tunnel is just transport. Your credentials are never used on the bastion and never exposed to it, which is the difference between this and forwarding your agent, where a compromised bastion can use your key.", "scp -o ProxyJump=bastion. Capital P for scp ports.", "A locked lobby before the office floor.", "man ssh_config | head", "ssh_config(5)", "Config beats 12 flags you will forget.", "Why not Disable StrictHostKeyChecking?", "You silently accept impostors.", ["host-config"], "One bastion, key auth, and a config file scale better than a mesh of passwords.", { mistakes: ["Forwarding the SSH agent to a shared bastion as the default. Anyone with root there can use your loaded keys for as long as you are connected.", "Repeating long connection flags on every command. They are forgotten on the one occasion it matters, and file transfer tools need the same options spelled differently."], practices: ["Put the jump configuration in ~/.ssh/config per host, so ssh, scp and rsync all use it automatically without any flags.", "Prefer jumping over agent forwarding. It achieves the same reach without trusting the intermediate machine with your credentials."], exercise: { prompt: "Add a Host block to ~/.ssh/config with `ProxyJump bastion` for a host you reach that way, then connect using just its name.", solution: "A single ssh <name> now opens both hops. Because the configuration lives in the file rather than the command, scp and rsync to that host take the same route with no extra arguments — which is the real benefit." } }),
  ],
  "package-managers": [
    cx("update-then-install", "Update the index, then install", "A package manager keeps a local list of what is available and where to download it. That list is a cached copy, and it goes stale. When a distribution publishes new versions, the old files are often removed from the mirrors, so an install using a stale list tries to fetch a URL that no longer exists and fails with a 404 rather than anything that explains itself. Refreshing the list first is not a ritual; it is the step that makes the addresses correct. On Debian-family systems this is a separate command, which is exactly why it gets forgotten.", "Pin versions in production images. Mixing pip --break-system-packages with apt Python is how boxes rot.", "Check the catalog, then order.", "man 8 apt | head || man dnf | head", "APT(8)", "Use the local family's man page.", "dpkg vs apt?", "dpkg unpacks a .deb you already have. apt finds, downloads, and resolves deps, then calls dpkg.", ["production-linux"], "Never wget a random .deb onto a production host.", { mistakes: ["Running apt install in a Dockerfile without apt update in the same step. The cached list from the base image can be months old and the files it names already gone.", "Treating a 404 during install as a broken mirror. It is usually a stale index pointing at a version that has been superseded and removed."], practices: ["Combine the refresh and the install in one command in any automated build, so a cached layer cannot leave a stale list behind.", "Pin exact versions for anything that must be reproducible. Without a pin, the same build file produces different software on different days."], exercise: { prompt: "Run `apt-cache policy bash` on a Debian-family system, or `dnf info bash` on a Red Hat one, and read the installed and candidate versions.", solution: "The candidate is what you would get from the current index. If it looks older than you expect, the index is stale and a refresh will change the answer — which is the whole reason the separate step exists." } }),
    cx("hold-pin", "Holds and pins", "Occasionally a package must not be upgraded. A kernel update breaks a driver you depend on, or an application is certified against one version of a library and not the next. Package managers let you freeze a package so ordinary upgrades skip it, which is a genuinely useful tool and a dangerous one, because frozen packages stop receiving security updates and nothing reminds you. The entire risk is forgetting. A hold put in place for a fortnight, undocumented, is still there two years later, and the machine is quietly missing patches nobody can explain.", "Document why the hold exists or you will debug ghosts in a year.", "A 'do not restock' tag on a shelf.", "apt-mark showhold 2>/dev/null || echo 'RPM family uses versionlock'", "", "Empty hold list is normal.", "Partial upgrade risk on Debian?", "Mixing old and new libs. Prefer full-upgrade in a window, or immutable images.", ["host-config"], "If you freeze a package, write down the ticket number.", { mistakes: ["Holding a package without recording why and when. Later it looks deliberate and permanent, and nobody dares remove it.", "Forgetting that a held package stops getting security fixes. The upgrade is not deferred, it is declined, every time until the hold is lifted."], practices: ["Write the reason, the date and the condition for removal next to every hold — in a ticket, a config comment, or the host's documentation.", "List the holds on any machine you inherit before trusting that it is fully patched. They are invisible in a normal upgrade run."], exercise: { prompt: "Run `apt-mark showhold` on a Debian-family system, or `dnf versionlock list` on a Red Hat one.", solution: "An empty list is the healthy answer and the usual one. Anything listed is a package deliberately excluded from updates, including security updates — and each entry should have a reason somebody can state." } }),
  ],
  "bash-scripting": [
    cx("shebang", "The shebang chooses the interpreter", "The first line of a script decides which interpreter runs it. If the file begins with a hash and an exclamation mark followed by a path, the kernel reads that line and starts the named program with your file as its input. This is why a script with no such line behaves unpredictably — whatever happened to run it decides, and that may not be the shell you wrote for. There is a meaningful choice here too: naming bash directly ties you to its location, while going through env finds bash wherever it is installed, which matters because it is not in the same place on every system.", "Windows CRLF breaks shebangs. chmod +x is required to exec the file; bash file.sh does not need +x.", "A note on the script saying which chef to call.", "head -n 1 /bin/true 2>/dev/null || echo 'binary — scripts start with #'", "", "Your scripts should start with #!/usr/bin/env bash or sh.", "Why env bash?", "bash is not always in /bin (Nix, some BSDs).", ["quoting-expansion"], "Match the shebang to the language you actually used (no Bash arrays in sh).", { mistakes: ["Writing a script with bash features but declaring #!/bin/sh. On most systems that is a smaller shell, and arrays and double-bracket tests fail with confusing syntax errors.", "Saving a script with Windows line endings. The carriage return becomes part of the interpreter path, and the error claims the interpreter does not exist when it plainly does."], practices: ["Use #!/usr/bin/env bash for anything using bash features, and #!/bin/sh only when the script is genuinely portable.", "If a script fails with a 'bad interpreter' error, check for carriage returns with file or cat -A before doubting the path."], exercise: { prompt: "Create a one-line script, make it executable, and run it. Then run `file` on it. Add a carriage return with `sed -i 's/$/\\r/' script.sh` and try running it again.", solution: "file reports it as a shell script with CRLF line terminators once broken, and running it fails with a bad interpreter error naming something that looks correct. The invisible carriage return is part of the path being looked up." } }),
    cx("set-e-pitfalls", "set -e is help, not a proof", "A shell script does not stop when a command fails. It carries on to the next line, which means a script whose first step failed can happily proceed to delete, deploy or overwrite as though everything worked. Turning on set -e makes the shell exit on failure instead, and it is the right default. But it is not a guarantee, and believing it is causes its own bugs: it deliberately does not fire for commands inside a condition, and by default it does not notice a failure anywhere in a pipeline except the last command. For anything genuinely important, check the result yourself.", "shellcheck catches a lot. Do not ignore SC warnings you do not understand.", "A seatbelt, not a helmet.", "help set | head", "set: set [--abefhkmnptuvxBCEHPT] ...", "Read set -e, -u, -o pipefail together.", "When is set -e skipped?", "In the condition of if, while, and some &&/|| lists — read the Bash manual before you trust it.", ["practical-scripts"], "Quote, check, and shellcheck. set -euo pipefail is the start, not the finish.", { mistakes: ["Assuming set -e covers pipelines. curl url | tar -x succeeds as far as the shell is concerned if tar succeeds, even when the download failed entirely.", "Relying on set -e inside a function called in a condition. It is suppressed there by design, which is surprising exactly when it matters."], practices: ["Use set -euo pipefail together. The three cover failure, undefined variables and pipelines, and each catches a different class of silent bug.", "Run shellcheck on every script. It finds the quoting and set -e gaps reliably, and its warnings are worth reading rather than silencing."], exercise: { prompt: "Write a script with `set -e`, then `false | true`, then `echo reached`. Run it. Add `set -o pipefail` and run it again.", solution: "The first run prints 'reached' — the pipeline reported true's success and the failure vanished. With pipefail the script stops. That difference is the one behind most 'it reported success but did nothing' build failures." } }),
  ],
  "pipes-redirection": [
    cx("order-of-redir", "Redirection order is the trick question", "Redirections are processed strictly left to right, and this makes one common pattern mean the opposite of what people expect. Writing >file 2>&1 first sends normal output to the file, then says errors should go wherever normal output currently goes — which is now the file. Both end up captured. Reversing them does not reverse the meaning symmetrically: 2>&1 >file first points errors at the terminal, where output currently goes, and only then moves normal output to the file. Errors stay on the terminal. The order is not a style preference; it changes which stream you captured.", "Left to right. 2>&1 copies the current stdout.", "Plumbing valves in sequence.", "echo hi > /tmp/out 2>&1", "", "Both streams follow stdout into the file.", "What does | do to PIDs?", "Two processes; kernel buffer between them. Writers block when full.", ["bash-scripting"], "Say the redirections out loud left to right before you press enter.", { mistakes: ["Writing cmd 2>&1 >log expecting both streams in the file. Errors go to the terminal and are lost from the log, usually discovered when something failed and the log is silent.", "Capturing a command's output in a variable and wondering why errors still appear on screen. Only normal output was captured; errors were never redirected."], practices: ["Prefer the shorthand &>file in bash when you want everything in one place. It is unambiguous and cannot be written in the wrong order.", "Keep the streams separate when it helps: cmd >out.log 2>err.log makes it immediately obvious whether anything went wrong."], exercise: { prompt: "Run `ls /nonexistent > /tmp/a 2>&1; cat /tmp/a` then `ls /nonexistent 2>&1 > /tmp/b; cat /tmp/b`.", solution: "The first file contains the error message; the second is empty and the error appeared on your terminal instead. Same two redirections, opposite results, decided entirely by the order." } }),
    cx("tee-and-pipefail", "tee and hidden failures", "tee copies what passes through it: output continues to the screen and is written to a file at the same time, which is why it is everywhere in build scripts and installers. It introduces a trap, though. In a pipeline, the shell reports only the last command's result by default, and the last command is tee — which almost always succeeds, because writing to a file usually works. So a failing command piped into tee produces a log full of errors, and a script that believes everything went fine and carries on to the next step.", "Use set -o pipefail or PIPESTATUS.", "A T-junction in a pipe.", "echo hello | tee /tmp/t | cat", "hello", "tee is not a backup system.", "When is a pipeline's exit status 0 despite a fail?", "Default: last command. grep finding nothing is status 1 — that surprises CI.", ["practical-scripts"], "If a pipeline matters, enable pipefail or check PIPESTATUS.", { mistakes: ["Ending a pipeline with tee in a script without pipefail. The script's exit status reflects tee's success, hiding whatever failed upstream.", "Using tee as a substitute for a real log. It captures only what the command wrote to standard output, so errors are missing unless they were redirected too."], practices: ["Turn on pipefail in any script containing pipelines whose failure matters. It makes the pipeline report the first failure rather than the last command.", "Check PIPESTATUS in bash when you need the result of a specific stage rather than the pipeline as a whole."], exercise: { prompt: "Run `false | tee /tmp/x; echo $?` then `set -o pipefail; false | tee /tmp/x; echo $?`.", solution: "The first prints 0 because tee succeeded. The second prints 1. Any build or deployment pipeline ending in tee without pipefail is reporting the status of the logging, not the work." } }),
  ],
  "practical-scripts": [
    cx("find-print-first", "find: print before delete", "find walks a directory tree and acts on everything matching your criteria, which is exactly as powerful and as dangerous as it sounds. The discipline that separates a careless operator from a careful one is a single habit: run it first with nothing but a print, read the list, and only then add the action. The reason is that find is recursive and silent. A pattern slightly wider than you intended does not warn you, and a delete action gives no summary and no confirmation. The list you did not read is the list you deleted.", "-print0 | xargs -0 for spaces. -xdev stays on one filesystem.", "Look in the fridge before throwing food.", "find . -name '*.tmp' -print | head", "(paths)", "Preview is the professional step.", "Why xargs without -0 is unsafe?", "Spaces and quotes split names. -print0 / -0 is the contract.", ["quoting-expansion"], "Preview, then mutate. Especially with find and rm.", { mistakes: ["Copying a find command with -delete from a web page and running it directly. The pattern was written for someone else's directory layout.", "Forgetting that find crosses filesystem boundaries by default. A cleanup intended for one disk can walk into a mounted backup or network share."], practices: ["Always run the command with -print first and read the output. If the list is too long to read, the pattern is too broad to run.", "Use -print0 with xargs -0 when filenames may contain spaces, and -xdev to stay on a single filesystem."], exercise: { prompt: "Run `find /tmp -name '*.log' -print` and count the results with `| wc -l` before considering any action on them.", solution: "You see exactly what would be affected. This is the entire safety practice — the preview costs one command and is the difference between a cleanup and an incident." } }),
    cx("cron-path", "Cron has a tiny PATH", "A job that works perfectly when you run it, and does nothing when cron runs it, is almost always the same problem. Cron does not start your shell the way logging in does. It does not read your profile, so none of the PATH additions, aliases or version-manager setup from your interactive session exist. A command you type by name every day is simply not found, and because cron's output goes nowhere by default, there is no error message anywhere. It fails silently, on schedule, until somebody notices the thing it was supposed to do never happened.", "Redirect stdout/err to a log. systemd timers are easier to debug with journalctl.", "A night shift worker who does not know your desk layout.", "crontab -l 2>/dev/null || echo 'no user crontab'", "", "Empty is fine.", "Why did cron skip my script?", "Missing shebang, CRLF, PATH, cwd, or mail of errors you never read.", ["logs-and-jobs"], "Write cron jobs as if the environment is empty — because it is.", { mistakes: ["Assuming a cron job inherits your environment. It inherits almost nothing, and the gap is invisible until something depends on it.", "Leaving a cron job's output undirected. Failures vanish, and the only evidence is the absent result."], practices: ["Use absolute paths for every command in a cron job, or set PATH explicitly at the top of the crontab.", "Redirect both streams to a log file. A job with no log cannot be diagnosed after the fact, which is exactly when you need to."], exercise: { prompt: "Add a temporary cron entry running `* * * * * env > /tmp/cronenv` and compare the result with `env` in your shell.", solution: "The cron environment is a handful of variables with a short PATH, usually without /usr/local/bin and without anything your profile added. Every 'works by hand, fails in cron' problem is visible in that difference." } }),
  ],
  systemd: [
    cx("enable-vs-start", "enable versus start", "Two different questions get confused constantly: is this service running now, and will it be running after a reboot. Starting a service affects only the present. Enabling it records that it should start at boot, and changes nothing about the current state. They are independent, which gives four possible combinations, and two of them are the ones that cause incidents: a service you started but never enabled disappears at the next reboot, and a service you enabled but never started is not actually running despite the configuration looking correct.", "systemctl cat shows the merged unit. systemctl edit writes a drop-in so upgrades do not wipe you.", "Hiring for today vs putting them on the permanent roster.", "systemctl is-enabled ssh 2>/dev/null || systemctl is-enabled sshd", "enabled", "Names differ by distro: ssh vs sshd.", "Where must you not edit?", "/lib/systemd/system or /usr/lib — package files. Use drop-ins in /etc.", ["logs-and-jobs"], "Drop-ins over rewriting vendor units.", { mistakes: ["Starting a service after installing it and never enabling it. It works until the first reboot, which may be months later and in the middle of the night.", "Reading 'enabled' as 'running'. The status is about boot behaviour; a separate line reports whether it is active right now."], practices: ["Use systemctl enable --now to do both in one step. It removes the entire class of mistake.", "Check both properties when verifying a deployment: systemctl is-active and systemctl is-enabled answer the two independent questions."], exercise: { prompt: "Run `systemctl is-enabled ssh || systemctl is-enabled sshd` and `systemctl is-active ssh || systemctl is-active sshd`.", solution: "You get two separate answers — typically enabled and active. A service reporting active but disabled is the dangerous combination: working now, gone after the next reboot, with nothing in its current status to warn you." } }),
    cx("type-simple", "Type=simple versus forking", "systemd needs to know how your program behaves on startup so it can tell whether it worked. The default assumes the command you give it is the service itself and keeps running. Some older programs do the opposite: they start, detach into the background, and the original command exits immediately — which systemd reads as the service having stopped the instant it began. Declaring the right type is what makes the difference between a service that reports started and one that reports started and immediately dead. The symptom is distinctive: it appears to work, and the status says failed.", "notify and Type=exec are modern. Read the unit before you guess.", "A manager who stays on the floor versus one who hires someone and leaves.", "man systemd.service | head", "SYSTEMD.SERVICE(5)", "This page is worth a slow read once.", "Restart=on-failure loop?", "Crash loop. Check journalctl -u and ExecStart path.", ["process-model"], "Match Type= to how the binary actually lives.", { mistakes: ["Leaving the default type for a program that detaches itself. systemd sees the launcher exit, concludes the service died, and may restart it in a loop.", "Adding a flag that makes a program background itself while keeping the default type. Many daemons have such a flag and it should normally be turned off under systemd."], practices: ["Run the program in the foreground where the option exists. systemd handles the backgrounding, and the service is simpler and more reliable for it.", "Read the merged unit with systemctl cat before guessing, and make changes with systemctl edit so a package upgrade does not overwrite them."], exercise: { prompt: "Run `systemctl cat ssh 2>/dev/null || systemctl cat sshd` and find the Type and ExecStart lines.", solution: "Most modern units either declare no Type, meaning simple, or Type=notify. ExecStart typically includes a flag telling the daemon not to background itself — that pairing is what keeps systemd's view of the service accurate." } }),
  ],
  "logs-and-jobs": [
    cx("journal-boot", "journalctl -b is this boot", "-u unit, -f follow, -p err priority, --since today. Persistent journals live in /var/log/journal.", "Rate limits hide floods. vacuum if journals eat the disk.", "A black box recorder with filters.", "journalctl -b -p err --no-pager | tail", "(errors)", "Empty is a good day.", "syslog files vs journal?", "rsyslog may still write /var/log/syslog. Distros often run both.", ["host-config"], "Start with journalctl -u name -b before you grep random files."),
    cx("timers-vs-cron", "Timers versus cron", "A .timer unit with OnCalendar= plus a matching .service. Persistent=true catches up after downtime. Logs land in the journal.", "cron is fine and portable. New work on systemd hosts is often easier as a timer.", "A calendar invite systemd honors.", "systemctl list-timers --all | head", "NEXT LEFT LAST UNIT", "If the table is empty, no timers.", "OnCalendar daily 01:30?", "*-*-* 01:30:00 in the timer unit.", ["practical-scripts"], "Prefer timers when you already live in systemd; keep cron for portable one-liners."),
  ],
  "host-config": [
    cx("ntp-tls", "Wrong time breaks TLS", "Certificates are only valid in a time window. NTP/chrony/timedatectl must be active. Servers should use UTC.", "timedatectl set-ntp true. chronyc tracking on some distros.", "A clock that is 3 days off will reject 'today's' tickets.", "timedatectl | head", "NTP service: active", "If inactive, fix time before chasing 'random' curl errors.", "Why UTC in logs?", "No DST jumps; correlate fleets; convert in the UI.", ["linux-security"], "Time sync is a security control, not a nicety."),
    cx("sshd-t", "sshd -t before reload", "A bad sshd_config can lock you out. Test, then reload, with a second session still open.", "PasswordAuthentication no, PermitRootLogin no, AllowUsers. Cloud security groups still need 22 or your bastion port.", "Proofread the lock before you close the door.", "man sshd_config | head", "SSHD_CONFIG(5)", "The real flag list.", "PermitRootLogin prohibit-password?", "Root may use keys, not passwords — still better to forbid root SSH and sudo from a user.", ["remote-access"], "Never restart sshd as the last open session without -t and a backup login."),
  ],
  "disks-partitions": [
    cx("lsblk-first", "lsblk is the pause button", "Before fdisk or mkfs, lsblk -f: size, TYPE, FSTYPE, UUID, MOUNTPOINT. If it is mounted, you are about to destroy data.", "NVMe is nvme0n1p2, not sda. Virtio is vda. Tutorials lie.", "Look at the warehouse map before you paint.", "lsblk -o NAME,SIZE,TYPE,FSTYPE,MOUNTPOINT", "(table)", "MATCH the device you think you have.", "GPT vs MBR in one line?", "GPT is modern 64-bit tables; MBR is legacy with a 2TiB-ish cap and four primary slots.", ["lvm-and-fstab"], "The professional disk skill is restraint plus lsblk."),
    cx("uuid-not-sda", "UUID in fstab, not /dev/sda", "Device names reorder. UUID stays with the filesystem. blkid prints them.", "PARTUUID is the partition table id; UUID is the filesystem id. Do not mix them up.", "A passport number versus a seat number that changes every flight.", "blkid | head", "UUID=\"...\" TYPE=\"ext4\"", "Copy from here into fstab.", "Why did / mount the wrong disk after adding a volume?", "fstab used /dev/sdb and names shifted. Use UUID.", ["mounts"], "Stable names: UUID, /dev/disk/by-uuid, or by-label."),
  ],
  "lvm-and-fstab": [
    cx("df-then-du", "df is the gauge; du is the compartments", "df -hT: which mount is full. df -i: inodes. du -xhd1: biggest directory on that filesystem only.", "Deleted-open files: df high, du low. Then lsof.", "Fuel gauge vs opening the trunk.", "df -hT | head", "Filesystem Type Size Used", "Always pair with df -i when create-file fails.", "50% df but cannot create files?", "Inodes, quotas, read-only remount, or permissions — not always 'disk full'.", ["performance-basics"], "Measure the mount, then the directory, then open files."),
    cx("grow-lv", "Growing a disk is three steps", "Cloud volume grow → grow partition/PV → lvextend → grow the filesystem (resize2fs or xfs_growfs). Missing the last step leaves df unchanged.", "XFS cannot shrink. Snapshots first.", "Lengthening a hose, then telling the water the hose is longer.", "man lvextend | head", "LVEXTEND(8)", "Read the man page on the actual host.", "Why df unchanged after lvextend?", "Filesystem not grown.", ["disks-partitions"], "Block device, LVM, filesystem — three layers, three commands."),
  ],
  "linux-security": [
    cx("selinux-not-off", "Do not setenforce 0 as a fix", "SELinux denials look like Permission denied. Read the AVC (ausearch, journal) and add a policy or fix the context. Permanent Permissive hides bugs.", "Ubuntu often AppArmor instead. ls -Z shows labels on SELinux hosts.", "Building rules that apply even to the owner.", "getenforce 2>/dev/null || echo 'no getenforce — check aa-status'", "Enforcing", "Enforcing is the goal on RHEL-like prod.", "AVC?", "Access Vector Cache denial — SELinux said no. It is a log line, not a virus.", ["production-linux"], "Treat MAC denials as data. Disabling the MAC is an incident of its own."),
    cx("least-privilege", "Least privilege is a habit", "Separate users, no shared root SSH, firewall allowlists, secrets 600, no 777, no secret in git.", "Capabilities split root. seccomp reduces syscalls. That is how containers harden.", "Only the keys you need today.", "id", "uid=1000(student) ...", "You should rarely need uid 0 on a laptop lesson — and even less on a server.", "sudo chmod 777 to make an app work?", "Never as policy. Fix owner, group, and mode; then MAC.", ["users-groups"], "Every 777 and every shared root key is a future incident."),
  ],
  "performance-basics": [
    cx("load-not-percent", "Load average is not CPU%", "It is a queue length (runnable + uninterruptible), averaged. Compare to CPU count. Load 32 on 4 vCPUs is saturation.", "vmstat r and wa split CPU vs disk. First vmstat line is since boot — ignore it.", "How many people are in line, not how loud the cashier is.", "uptime; vmstat 1 3", "load average: ...", "Sample lines after the first.", "High load, idle CPU?", "Often D-state I/O or NFS. iostat and dmesg next.", ["memory-ipc"], "USE method: utilization, saturation, errors — then change one thing."),
    cx("cache-is-not-waste", "Linux uses free RAM for cache", "free's available is what you can still allocate. Huge 'used' that is cache is healthy. Dropping caches is a last-resort test, not a tune.", "OOM killer fires when reclaim fails. Watch dmesg for oom-kill.", "Books left open on a table — still reusable.", "free -h", "Mem: ... available ...", "Read available, not used.", "Should you disable swap?", "On tiny VMs it can prevent death-by-thrash or cause OOM sooner. Know the tradeoff; do not cargo-cult.", ["memory-ipc"], "Cache is working as designed. Panic at low available plus paging, not at a full cache."),
  ],
  "tcp-and-sockets": [
    cx("time-wait", "TIME-WAIT is not a leak", "A closed TCP connection waits so delayed packets do not confuse a new connection. Huge counts can exhaust ephemeral ports under load tests.", "ss -tan | grep TIME. Tuning tw reuse is a last resort behind NAT.", "Lingering at the counter so a late letter is not misread.", "ss -tan | head", "State ...", "Count ESTAB vs TIME-WAIT during tests.", "Connection refused vs timeout?", "Refused: RST, reachable host, no listener. Timeout: drop, routing, or filter.", ["net-fundamentals"], "Sockets are file descriptors. ulimit -n matters under load."),
    cx("ephemeral", "Ephemeral ports", "Outbound connections pick a high local port. Exhaustion looks like 'cannot connect' under load. ss + nstat help.", "ip_local_port_range sysctl. Connection pooling reduces churn.", "Temporary ticket numbers at a deli.", "sysctl net.ipv4.ip_local_port_range", "32768 60999", "Typical Linux default range.", "TIME-WAIT pile + port exhaustion?", "Reuse connections, scale out, or (carefully) tune. Measure first.", ["performance-basics"], "Load-test with ss open. Port exhaustion is a real production bug."),
  ],
  "namespaces-cgroups": [
    cx("not-a-vm", "A container is not a VM", "Same kernel. Isolated view (namespaces) and meters (cgroups). PID 1 inside is not host systemd. Privileged containers punch holes.", "User namespaces map UIDs. Overlay FS is the layered disk illusion.", "Different windows on the same city, plus an electricity meter.", "lsns | head", "NS TYPE NPROCS ...", "In a container the PID ns is short.", "Why Docker on Mac is slower?", "It runs a Linux VM. Namespaces are a Linux kernel feature.", ["memory-ipc"], "If you understand namespaces + cgroups, Kubernetes questions get easier."),
    cx("cgroup-limit", "When the app is 'slow' check the quota", "CPU and memory limits in cgroups look like a weak machine. docker stats / kubectl top. OOMKill is a cgroup event too.", "cgroup v2 is a unified tree. systemd slices are cgroups.", "A breaker panel for each apartment.", "man cgroups | head", "CGROUPS(7)", "Worth one slow read.", "throttled CPU?", "cfs quota. The host may be idle while the container is capped.", ["performance-basics"], "Limits are features. They also create fake 'hardware' symptoms."),
  ],
  "memory-ipc": [
    cx("page-cache", "Page cache in one sentence", "RAM remembers file contents so the next read skips disk. Clean pages can be dropped instantly; dirty pages must write back first.", "vmtouch and /proc/meminfo Cached. fsync forces durability.", "Keeping the cookbook open on the counter.", "grep -E 'Cached|Dirty|MemAvailable' /proc/meminfo", "Cached: ...", "Numbers in kB.", "Why shutdown is slow?", "Dirty writeback. Lots of recent writes.", ["performance-basics"], "Free RAM that becomes cache is a win, not a leak."),
    cx("ulimit-files", "Too many open files", "Each socket and file is an fd. ulimit -n is the cap. nginx and databases hit this first.", "systemd LimitNOFILE=. The hard limit is a ceiling.", "A handful of tickets you are allowed to hold.", "ulimit -n", "1024", "Many servers raise this on purpose.", "EMFILE?", "Process hit its fd limit. Count /proc/PID/fd and check leaks.", ["tcp-and-sockets"], "Sockets are files. Treat fd limits as capacity planning."),
  ],
  "unix-posix": [
    cx("gnu-flags-on-mac", "macOS is Unix, not GNU", "ls, find, and sed flags differ. Homebrew coreutils install gtimeout etc. systemd and /proc are absent.", "POSIX is the overlap. Test portable scripts on dash.", "Same language family, different slang.", "uname -s", "Linux  (here) or Darwin (Mac)", "Scripts should check or stick to POSIX.", "ps aux on Mac?", "Works (BSD). Linux ps also takes -ef. AIX may not like aux.", ["linux-vs-unix"], "Write POSIX first. Document GNU extensions in the README."),
    cx("sbin-admin", "Why some commands live in sbin", "Traditionally admin tools (fsck, ip) were in sbin and not on a user PATH. Merged /usr blurs this. Still appears in interviews.", "Need root for the action, not always to see the binary.", "A locked tools closet.", "command -v ip || ls /usr/sbin/ip", "/usr/sbin/ip", "May need to prepend /usr/sbin on some Unixes.", "Why 'command not found' as a user but root works?", "root PATH includes sbin.", ["env-and-path"], "Check PATH and sbin before reinstalling the package."),
  ],
  "production-linux": [
    cx("reversible-change", "Every change needs an undo", "Deploy is not done until rollback is typed. systemd, images, and config management exist so you can reverse.", "Pet servers without backups are hopes, not plans.", "A restaurant ticket you can void.", "systemctl is-system-running 2>/dev/null || echo 'check PID 1'", "running", "degraded means failed units.", "Sev1 first minute?", "Stop bleeding, communicate, preserve evidence, then root-cause. Do not chmod 777.", ["linux-security"], "Production is Linux plus change control, observability, and backups."),
    cx("immutable-idea", "Cattle, not pets", "Replace VMs/images instead of SSHing a unique snowflake. SSH still exists for break-glass.", "Cloud-init, golden images, Kubernetes pods. The kernel skills stay the same.", "A rental car you do not customize with stickers.", "echo 'this host should be reproducible'", "this host should be reproducible", "If you cannot rebuild it, you do not own it.", "Why still learn SSH and journalctl?", "Break-glass and because the thing you orchestrate is still Linux.", ["namespaces-cgroups"], "Automate the boring path. Keep the kernel skills for the 3 a.m. path."),
  ],
};
